scwin.trigger1_onclick = function(e) {
    var options={
        "colMerge" : "true",
        "fileName" : "병합테스트.xlsx",
         "colMergeValue":"true",
        "bodyWordwrap" : "true", 
        "mergeCell" : "true"
    };
    grd_corrAssnRule.advancedExcelDownload(options)
};

	scwin.setSimulate = function() {
		alert(1)
		scwin.simulateWrapper('#grd_corrAssnRule_cell_0_0', 'key-combo', {
			combo: 'shift+right-arrow'
		});
	}
	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}

	scwin.checkVal = function() {
	alert(2)
		let first_reValue = false;
		let second_reValue = false;
		const rows = WebSquare.wUnit.getDomById('mf_grd_corrAssnRule_body_tbody').children[0].querySelectorAll('td');
		debugger;
		rows.forEach((row, rowIndex) => {
			if (rowIndex == 0) {
				first_reValue = row.classList.contains('focusedTd');
			}else if (rowIndex == 1) {
				second_reValue = row.classList.contains('focusedTd');
			}
		});
		return first_reValue && second_reValue;
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_corrAssnRule_cell_0_0').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand('pause', '500');	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
